// Closest Java equivalent: a producer thread and a queue with n slots (n >= 1 here)
static <T> void myBuffer(Iterable<T> upstream, int n, Consumer<T> downstream) throws InterruptedException {
    BlockingQueue<Optional<T>> spots = new ArrayBlockingQueue<>(n);
    Thread producer = Thread.ofVirtual().start(() -> {   // 1. a second thread runs the upstream
        try {
            for (T v : upstream) spots.put(Optional.of(v)); //    put blocks only when all n slots are full
            spots.put(Optional.empty());                    // 2. the end marker lets the loop below end
        } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    });
    for (Optional<T> v = spots.take(); v.isPresent(); v = spots.take()) downstream.accept(v.get());   // 3.
    producer.join();
}
